def num_permutations(n, k, p):
    def stirling_number_of_the_second_kind(n, k):
        if n == k == 0:
            return 1
        if n == 0 or k == 0:
            return 0
        return k * stirling_number_of_the_second_kind(n - 1, k) + stirling_number_of_the_second_kind(n - 1, k - 1)

    def factorial_mod_prime(n, p):
        result = 1
        for i in range(2, n + 1):
            result = (result * i) % p
        return result

    def binomial_coefficient_mod_prime(n, k, p):
        return factorial_mod_prime(n, p) * mod_inv(factorial_mod_prime(k, p) * factorial_mod_prime(n - k, p), p) % p

    total_permutations = factorial(n)
