        return pow(x, p-2, p)

    def binomial_coefficient(n, k, p):
        if k > n:
            return 0
        numerator = factorial(n) % p
        denominator = (factorial(k) * factorial(n - k)) % p
        return (numerator * mod_inv(denominator, p)) % p

