MOD = int(1e9 + 9)

def binpow(a, b):
    res = 1
    while b > 0:
        if b % 2 == 1:
            res = res * a % MOD
        a = a * a % MOD
        b //= 2
    return res

def inverse(a):
    return binpow(a, MOD - 2)

def catalan_number(n):
    C = [0] * (n + 1)
    C[0] = 1
    for i in range(1, n + 1):
        C[i] = sum(C[j] * C[i - j - 1] for j in range(i)) % MOD
    return C[n]

def dp(n, k):
    if n <= 1:
        return 1
    C = catalan_number(n)
    dp_table = [0] * (n + 1)
    dp_table[0] = 1
    dp_table[1] = 1
    for i in range(2, n + 1):
        dp_table[i] = (dp_table[i - 1] * (i + 1) - dp_table[i - k]) % MOD
    return dp_table[n] * inverse(C) % MOD

